33	    @Mapping(target = "possibleDuplicate", ignore = true)
34	    @Mapping(target = "possibleDuplicateOf", ignore = true)
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * Derives the owner's {@code contactPreference} from the owner's own fields:
39	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
40	     *
41	     * @param owner the owner being mapped
42	     * @return the derived contact preference
43	     */
44	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
45	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
46	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
47	    }
48	
49	    /**
50	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
51	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
52	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
53	     * case the field is absent from the response. The age in whole years is the number of complete
54	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
55	     * registration date is somehow absent the current date is used as the reference.
56	     *
57	     * @param owner the owner being mapped
58	     * @return the derived age band, or {@code null} when no birth date is present
59	     */
60	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
61	        java.time.LocalDate birthDate = owner.getBirthDate();
62	        if (birthDate == null) {
63	            return null;
64	        }
65	        java.time.LocalDate reference = owner.getRegistrationDate() != null
66	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
67	        int age = java.time.Period.between(birthDate, reference).getYears();
68	        if (age < 18) {
69	            return OwnerDto.AgeBandEnum.MINOR;
70	        }
71	        if (age < 65) {
72	            return OwnerDto.AgeBandEnum.ADULT;
73	        }
74	        return OwnerDto.AgeBandEnum.SENIOR;
75	    }
76	
77	    /**
78	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code customerCode}
79	     * (the part before the {@code '-'}), which is the owner's canonical region code baked into the
80	     * region-and-hash identity {@code '<REGION>-<HASH8>'}. When no customer code is present (e.g. seed
81	     * data) it falls back to resolving the region directly from the owner's {@code postcode} and
82	     * {@code city} through the shared {@link Region#code(String, String)}. Reading the region from the
83	     * identity keeps the locality consistent with the code an owner is issued.
84	     *
85	     * @param owner the owner being mapped
86	     * @return the derived locality
87	     */
88	    default String locality(Owner owner) {
89	        String code = owner.getCustomerCode();
90	        if (code == null) {
91	            return Region.code(owner.getPostcode(), owner.getCity());
92	        }
93	        int dash = code.indexOf('-');
94	        return dash >= 0 ? code.substring(0, dash) : code;
95	    }
96	
97	    /**
98	     * Derives the owner's numeric {@code membershipLevel} from the owner's own fields. Starts at
99	     * {@code 1}, adds {@code 1} when an email is present, and adds {@code 1} when the owner's
100	     * {@code namesakeCount} is {@code 0}. These pre-tenure factors are capped at {@code 3}. Level
101	     * {@code 4} is reserved for tenure: it is granted only when the owner's tenure &mdash; the number
102	     * of whole days between its {@code registrationDate} and the current date &mdash; exceeds
103	     * {@code 365}. Because a newly created owner has zero tenure, a new owner never exceeds level
104	     * {@code 3}, even with an email and a {@code namesakeCount} of {@code 0}.
105	     *
106	     * @param owner the owner being mapped
107	     * @return the derived membership level, between {@code 1} and {@code 4}
108	     */
109	    default Integer membershipLevel(Owner owner) {
110	        int level = 1;
111	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
112	        if (hasEmail) {
113	            level++;
114	        }
115	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
116	        if (uniqueName) {
117	            level++;
118	        }
119	        level = Math.min(level, 3);
120	        if (tenureDays(owner) > 365) {
121	            level++;
122	        }
123	        return level;
124	    }
125	
126	    /**
127	     * Computes the owner's tenure in whole days: the number of complete days between the owner's
128	     * {@code registrationDate} and the current date. Returns {@code 0} when no registration date is
129	     * present, so an owner without a registration date has no tenure.
130	     *
131	     * @param owner the owner being mapped
132	     * @return the owner's tenure in whole days, or {@code 0} when no registration date is present
133	     */
134	    default long tenureDays(Owner owner) {
135	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
136	        if (registrationDate == null) {
137	            return 0;
138	        }
139	        return java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
140	    }
141	
142	    /**
143	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
144	     * where {@code YY} is the last two digits of the {@code registrationDate} year (e.g.
145	     * {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null} when either the customer code or the
146	     * registration date is absent.
147	     *
148	     * @param owner the owner being mapped
149	     * @return the formatted membership number, or {@code null} when it cannot be derived
150	     */
151	    default String membershipNumber(Owner owner) {
152	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
153	            return null;
154	        }
155	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
156	    }
157	
158	    /**
159	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
160	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
161	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
162	     * the customer code is absent.
163	     *
164	     * @param owner the owner being mapped
165	     * @return the Luhn check digit, or {@code null} when no customer code is present
166	     */
167	    default Integer checkDigit(Owner owner) {
168	        String code = owner.getCustomerCode();
169	        if (code == null) {
170	            return null;
171	        }
172	        int sum = 0;
173	        boolean dbl = true;
174	        for (int i = code.length() - 1; i >= 0; i--) {
175	            char c = code.charAt(i);
176	            if (c < '0' || c > '9') {
177	                continue;
178	            }
179	            int d = c - '0';
180	            if (dbl) {
181	                d *= 2;
182	                if (d > 9) {
183	                    d -= 9;
184	                }
185	            }
186	            sum += d;
187	            dbl = !dbl;
188	        }
189	        return (10 - (sum % 10)) % 10;
190	    }
191	
192	    /**
193	     * Formats the owner's stored E.164 {@code telephone} for human display: the country calling
194	     * code, a space, then the national-significant digits grouped in threes separated by spaces
195	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw {@code telephone}
196	     * field keeps the unformatted E.164 value. The split between the country code and the national
197	     * digits mirrors the recognised calling codes of the {@code TelephoneNormalizer}: Australian
198	     * {@code +61} (9 national digits) and North American {@code +1} (10); an unrecognised or
199	     * malformed value falls back to a single leading digit. Returns the value unchanged when it is
200	     * {@code null}, blank, or not in E.164 form.
201	     *
202	     * @param owner the owner being mapped
203	     * @return the human-formatted telephone, or the raw value when it cannot be formatted
204	     */
205	    default String telephoneDisplay(Owner owner) {
206	        String telephone = owner.getTelephone();
207	        if (telephone == null || telephone.isBlank() || !telephone.startsWith("+")) {
208	            return telephone;
209	        }
210	        String digits = telephone.substring(1);
211	        int codeLength = (digits.startsWith("61") && digits.length() == 2 + 9) ? 2 : 1;
212	        String countryCode = digits.substring(0, codeLength);
213	        String national = digits.substring(codeLength);
214	        StringBuilder grouped = new StringBuilder();
215	        for (int i = 0; i < national.length(); i++) {
216	            if (i > 0 && i % 3 == 0) {
217	                grouped.append(' ');
218	            }
219	            grouped.append(national.charAt(i));
220	        }
221	        return "+" + countryCode + " " + grouped;
222	    }
223	
224	    Owner toOwner(OwnerDto ownerDto);
225	
226	    @Mapping(target = "id", ignore = true)
227	    @Mapping(target = "pets", ignore = true)
228	    Owner toOwner(OwnerFieldsDto ownerDto);
229	
230	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
231	
232	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
233	
234	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
235	        OwnerPageDto ownerPageDto = new OwnerPageDto();
236	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
237	        ownerPageDto.setPage(ownerPage.getNumber());
238	        ownerPageDto.setSize(ownerPage.getSize());
239	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
240	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
241	        return ownerPageDto;
242	    }
243	}
