68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    private final TelephoneNormalizer telephoneNormalizer;
86	
87	    private final AddressNormalizer addressNormalizer;
88	
89	    private final EmailNormalizer emailNormalizer;
90	
91	    private final DisposableEmailDomains disposableEmailDomains;
92	
93	    public OwnerRestControllerV1(ClinicService clinicService,
94	                                 OwnerMapper ownerMapper,
95	                                 PetMapper petMapper,
96	                                 VisitMapper visitMapper,
97	                                 TelephoneNormalizer telephoneNormalizer,
98	                                 AddressNormalizer addressNormalizer,
99	                                 EmailNormalizer emailNormalizer,
100	                                 DisposableEmailDomains disposableEmailDomains) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	        this.telephoneNormalizer = telephoneNormalizer;
106	        this.addressNormalizer = addressNormalizer;
107	        this.emailNormalizer = emailNormalizer;
108	        this.disposableEmailDomains = disposableEmailDomains;
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
114	        Collection<Owner> owners;
115	        if (lastName != null) {
116	            owners = this.clinicService.findOwnerByLastName(lastName);
117	        } else {
118	            owners = this.clinicService.findAllOwners();
119	        }
120	        if (owners.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        return withOwner(ownerId, owner ->
130	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
137	        rejectBlankOwnerFields(ownerFieldsDto);
138	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
139	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
140	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
141	        rejectCityAtCapacity(ownerFieldsDto.getCity());
142	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
143	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
144	        rejectDailyRegistrationLimit(registrationDate);
145	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
146	        ownerFieldsDto.setTelephone(normalizedTelephone);
147	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
148	        ownerFieldsDto.setEmail(normalizedEmail);
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        owner.setRegistrationDate(registrationDate);
152	        owner.setCustomerCode(customerCode(owner));
153	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
154	        owner.setHouseholdId(householdId(owner));
155	        rejectDuplicateIdentity(owner);
156	        rejectHouseholdDuplicate(owner, sharesHousehold);
157	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
158	        this.clinicService.saveOwner(owner);
159	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
160	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
161	            ownerMapper.membershipLevel(owner));
162	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
163	        headers.setLocation(UriComponentsBuilder.newInstance()
164	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
165	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
171	        return withOwner(ownerId, currentOwner -> {
172	            currentOwner.setAddress(ownerFieldsDto.getAddress());
173	            currentOwner.setCity(ownerFieldsDto.getCity());
174	            currentOwner.setFirstName(ownerFieldsDto.getFirstName());
175	            currentOwner.setLastName(ownerFieldsDto.getLastName());
176	            currentOwner.setTelephone(ownerFieldsDto.getTelephone());
177	            currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
178	            this.clinicService.saveOwner(currentOwner);
179	            return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
180	        });
181	    }
