250	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
251	            }
252	        }
253	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	    }
255	
256	    /**
257	     * Loads the owner with the given id and, when it exists, produces the response through
258	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
259	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
260	     * the not-found response are written in exactly one place rather than copied into each method.
261	     *
262	     * @param ownerId the id of the owner to load
263	     * @param action builds the response for an existing owner
264	     * @param <T> the response body type
265	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
266	     */
267	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
268	        Owner owner = this.clinicService.findOwnerById(ownerId);
269	        if (owner == null) {
270	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	        }
272	        return action.apply(owner);
273	    }
274	
275	    /**
276	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
277	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
278	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
279	     * return their owner through this method, so an owner is decorated identically on either path
280	     * and each derived field is computed in exactly one place.
281	     *
282	     * @param owner the persisted owner to represent
283	     * @return the owner DTO with its derived read-only fields populated
284	     */
285	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
286	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
287	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
288	        ownerDto.setIdentityKey(identityKey(owner));
289	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
290	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
291	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
292	        return ownerDto;
293	    }
294	
295	    /**
296	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
297	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
298	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
299	     * blank (e.g. {@code "   "}). The offending field names are reported through an
300	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
301	     * as a 400 response carrying an {@code errors} array of field names.
302	     *
303	     * @param ownerFieldsDto the submitted owner fields
304	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
305	     */
306	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
307	        List<String> blankFields = new ArrayList<>();
308	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
309	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
310	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
311	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
312	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
313	        if (!blankFields.isEmpty()) {
314	            throw new InvalidOwnerFieldsException(blankFields);
315	        }
316	    }
317	
318	    private void addIfBlank(List<String> blankFields, String field, String value) {
319	        if (value != null && value.isBlank()) {
320	            blankFields.add(field);
321	        }
322	    }
323	
324	    /**
325	     * Rejects an owner whose {@code email} domain is on the disposable-domain blocklist
326	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is validated
327	     * only when present, so an owner created without one is accepted unchanged; syntactic validity is
328	     * already enforced by Bean Validation's {@code @Email} constraint on {@link OwnerFieldsDto}, so
329	     * this only rejects an otherwise well-formed address that uses a throwaway provider (see
330	     * {@link DisposableEmailDomains#isDisposable(String)} for the case-insensitive domain match). A
331	     * blocklisted address is reported through a {@link DisposableEmailDomainException}, which the
332	     * {@code ExceptionControllerAdvice} renders as a 400 response naming the {@code email} field.
333	     *
334	     * @param email the supplied email, or {@code null} when omitted
335	     * @throws DisposableEmailDomainException if the email's domain is blocklisted
336	     */
337	    private void rejectDisposableEmailDomain(String email) {
338	        if (disposableEmailDomains.isDisposable(email)) {
339	            throw new DisposableEmailDomainException(email);
340	        }
341	    }
342	
343	    /**
344	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
345	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
346	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
347	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
348	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
349	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
350	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
351	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
352	     *
353	     * @param city the city of the owner being created
354	     * @param postcode the supplied postcode, or {@code null} when omitted
355	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
356	     */
357	    private void rejectInvalidPostcode(String city, String postcode) {
358	        if (postcode == null || postcode.isBlank()) {
359	            return;
360	        }
361	        Region.forCity(city).ifPresent(region -> {
362	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
363	                throw new InvalidOwnerPostcodeException(postcode, city);
364	            }
365	        });
366	    }
367	
368	    /**
369	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
370	     * the {@code customerCode}.
371	     */
372	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
373	
374	    /**
375	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
376	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
377	     * its {@code postcode} (falling back to its {@code city}) through the shared
378	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
379	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
380	     * (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a deterministic
381	     * function of the owner's region and telephone-plus-name identity.
382	     *
383	     * @param owner the owner being created, with its telephone already normalized
384	     * @return the formatted customer code
385	     */
386	    private String customerCode(Owner owner) {
387	        String region = Region.code(owner.getPostcode(), owner.getCity());
388	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
389	        return region + "-" + hash8;
390	    }
391	
392	    /**
393	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
394	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
395	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
396	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
397	     * new owner and surfaced as the read-only {@code namesakeCount} field.
398	     *
399	     * @param firstName the first name of the owner being created
400	     * @param lastName the last name of the owner being created
401	     * @return the number of existing owners with the same first and last name (case-insensitive)
402	     */
403	    private int namesakeCount(String firstName, String lastName) {
404	        return (int) this.clinicService.findAllOwners().stream()
405	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
406	                && equalsIgnoreCase(owner.getLastName(), lastName))
407	            .count();
408	    }
409	
410	    private boolean equalsIgnoreCase(String a, String b) {
411	        return a == null ? b == null : a.equalsIgnoreCase(b);
412	    }
413	
414	    /**
415	     * The maximum number of owners a single city may contain. Once a city already holds this many
416	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
417	     */
418	    private static final long MAX_OWNERS_PER_CITY = 50L;
419	
420	    /**
421	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
422	     * owners. Existing owners are matched to the requested city case-insensitively (using
423	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
424	     * the per-city counting used for the customer code. A city at capacity is reported through an
425	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
426	     * 409 Conflict response.
427	     *
428	     * @param city the city of the owner being created
429	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
430	     */
431	    private void rejectCityAtCapacity(String city) {
432	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
433	            throw new OwnerCityAtCapacityException(city);
434	        }
435	    }
436	
437	    /**
438	     * Counts the existing owners whose {@code city} matches the given city, compared
439	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Used by the per-city
440	     * capacity check ({@link #rejectCityAtCapacity(String)}) to count a city's owners.
441	     *
442	     * @param city the city to count owners for
443	     * @return the number of existing owners in that city
444	     */
445	    private long ownersInCity(String city) {
446	        return this.clinicService.findAllOwners().stream()
447	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
448	            .count();
449	    }
450	
451	    /**
452	     * The maximum number of owners that may be registered on a single day. Once this many owners
453	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
454	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
455	     */
456	    private static final long MAX_OWNERS_PER_DAY = 100L;
457	
458	    /**
459	     * Resolves the effective registration date for a create request: the value supplied in the
460	     * request when present, otherwise the server's current date. The result is the raw effective
461	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
462	     *
463	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
464	     * @return the supplied date, or today when none was supplied
465	     */
466	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
467	        return suppliedDate != null ? suppliedDate : LocalDate.now();
468	    }
469	
470	    /**
471	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
472	     * current date. A registration date may be supplied to backdate a create - and is defaulted to
473	     * today when omitted - but it may never be in the future. The check is applied to the raw
474	     * supplied value before the business-day adjustment ({@link #businessDay(LocalDate)}), so a
475	     * future date is rejected regardless of how that adjustment would move it. A future date is
476	     * reported through a {@link FutureRegistrationDateException}, which the
477	     * {@code ExceptionControllerAdvice} renders as a 400 Bad Request response naming the
478	     * {@code registrationDate} field.
479	     *
480	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
481	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
482	     */
483	    private void rejectFutureRegistrationDate(LocalDate suppliedDate) {
484	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
485	            throw new FutureRegistrationDateException(suppliedDate);
486	        }
487	    }
488	
489	    /**
490	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
491	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
492	     * the effective registration date so that a weekend value - whether supplied in the request or
493	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
494	     * registration date (such as the membership number's year segment and the daily create-limit
495	     * bucket) uses the adjusted business day.
496	     *
497	     * @param date the effective registration date
498	     * @return the same date when it is a weekday, otherwise the next Monday
499	     */
500	    private LocalDate businessDay(LocalDate date) {
501	        DayOfWeek dayOfWeek = date.getDayOfWeek();
502	        if (dayOfWeek == DayOfWeek.SATURDAY) {
503	            return date.plusDays(2);
504	        }
505	        if (dayOfWeek == DayOfWeek.SUNDAY) {
506	            return date.plusDays(1);
507	        }
508	        return date;
509	    }
510	
511	    /**
512	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
513	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
514	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
515	     * renders as a 429 Too Many Requests response.
516	     *
517	     * @param date the registration date of the owner being created (today)
518	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
519	     */
520	    private void rejectDailyRegistrationLimit(LocalDate date) {
521	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
522	            throw new DailyOwnerRegistrationLimitException(date);
523	        }
524	    }
525	
526	    /**
527	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
528	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
529	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
530	     * day's owners identically.
531	     *
532	     * @param date the registration date to count owners for
533	     * @return the number of existing owners registered on that day
534	     */
535	    private long ownersRegisteredOn(LocalDate date) {
536	        return this.clinicService.findAllOwners().stream()
537	            .filter(owner -> date.equals(owner.getRegistrationDate()))
538	            .count();
539	    }
540	
541	    /**
542	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
543	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
544	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
545	     */
546	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
547	
548	    /**
549	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
550	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
551	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
552	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
553	     * without a registration date, such as seed data) is never flagged.
554	     *
555	     * @param date the owner's registration date (the day it was created), or {@code null}
556	     * @return {@code true} if the day already holds more than the warning threshold of owners
557	     */
558	    private boolean bulkSignupWarning(LocalDate date) {
559	        if (date == null) {
560	            return false;
561	        }
562	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
563	    }
564	
565	    /**
566	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
567	     * The identity key consolidates the former separate telephone, email and household duplicate
568	     * checks into a single value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
569	     * (householdId or empty)} (see {@link #identityKey(Owner)}). Because the telephone is part of the
570	     * key, two members of the same household (same {@code householdId}) with different telephones have
571	     * different identity keys and are both allowed; only an exact full-key match is a duplicate. A
572	     * collision is reported through a {@link DuplicateOwnerIdentityException}, which the
573	     * {@code ExceptionControllerAdvice} renders as a 409 Conflict response.
574	     *
575	     * @param owner the fully-populated owner being created (telephone, email and household id set)
576	     * @throws DuplicateOwnerIdentityException if an existing owner has the same identity key
577	     */
578	    private void rejectDuplicateIdentity(Owner owner) {
579	        String key = identityKey(owner);
580	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
581	        if (duplicate) {
582	            throw new DuplicateOwnerIdentityException(key);
583	        }
584	    }
585	
586	    /**
587	     * Rejects a create request that would join an existing household unless it declares the shared
588	     * household with {@code sharesHousehold}. The household is keyed on {@code (lastName, postcode)}
589	     * through the deterministic {@link #householdId(Owner)}, so any existing owner with the same last
590	     * name and postcode is a member of the same household. A second such owner is a household
591	     * duplicate and is rejected with a 409 (via {@link DuplicateOwnerIdentityException}); setting
592	     * {@code sharesHousehold} bypasses this block, so the owner is created as a declared household
593	     * member instead. Owners without a {@code householdId} (e.g. no postcode) have no household to
594	     * collide with and are always allowed.
595	     *
596	     * @param owner the fully-populated owner being created (household id set)
597	     * @param sharesHousehold whether the request declared it shares an existing household
598	     * @throws DuplicateOwnerIdentityException if the household already exists and was not declared
599	     */
600	    private void rejectHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
601	        if (sharesHousehold) {
602	            return;
603	        }
604	        String household = owner.getHouseholdId();
605	        if (household == null) {
606	            return;
607	        }
608	        if (existingOwnerMatches(this::householdId, household)) {
609	            throw new DuplicateOwnerIdentityException(identityKey(owner));
610	        }
611	    }
612	
613	    /**
614	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
615	     * first existing owner that shares this owner's {@code lastName} (compared case-insensitively) and
616	     * {@code postcode} while carrying a <em>different</em> telephone (compared by canonical E.164 form,
617	     * see {@link TelephoneNormalizer#canonicalize(String)}), or {@code null} when no such owner exists.
618	     * The check runs only after the exact-identity duplicate check ({@link #rejectDuplicateIdentity(Owner)})
619	     * has passed, so a shared last-name-and-postcode with the same telephone has already been rejected as
620	     * a hard duplicate and can never surface here. A blank {@code postcode} never matches, since two
621	     * owners without a postcode do not share one. The captured id is stored on the new owner and surfaced
622	     * as the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
623	     *
624	     * @param owner the fully-populated owner being created (telephone normalized)
625	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
626	     */
627	    private Integer possibleDuplicateOf(Owner owner) {
628	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
629	            return null;
630	        }
631	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
632	        return this.clinicService.findAllOwners().stream()
633	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
634	                && owner.getPostcode().equals(existing.getPostcode())
635	                && !java.util.Objects.equals(telephone, telephoneNormalizer.canonicalize(existing.getTelephone())))
636	            .map(Owner::getId)
637	            .filter(java.util.Objects::nonNull)
638	            .findFirst()
639	            .orElse(null);
640	    }
641	
642	    /**
643	     * Reduces an owner to its derived {@code identityKey}, formatted
644	     * {@code '<normalizedTelephone>|<email>|<householdId>'}: the owner's telephone reduced to its
645	     * canonical E.164 form (see {@link TelephoneNormalizer#canonicalize(String)}), the owner's
646	     * normalized (lower-cased) email or the empty string when absent (see
647	     * {@link EmailNormalizer#normalize(String)}), and the owner's {@code householdId} or the empty
648	     * string when absent, joined by {@code '|'}. Two owners are duplicates exactly when their whole
649	     * identity keys are equal. The key never contains {@code null} segments, so the create endpoint's
650	     * single duplicate check compares this one value across owners.
651	     *
652	     * @param owner the owner to derive the identity key for
653	     * @return the owner's identity key
654	     */
655	    private String identityKey(Owner owner) {
656	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
657	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
658	        String email = normalizedEmail == null ? "" : normalizedEmail;
659	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
660	        return telephone + "|" + email + "|" + household;
661	    }
662	
663	    /**
664	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
665	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
666	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
667	     * checks reduce both an existing owner and the owner being created to the same canonical key;
668	     * this returns the matched existing owner itself, so a caller can either reject the collision or
669	     * record which owner was matched.
670	     *
671	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
672	     * @param key the canonical key of the owner being created
673	     * @return the first existing owner sharing the key, or empty when none does
674	     */
675	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
676	        return this.clinicService.findAllOwners().stream()
677	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
678	            .findFirst();
679	    }
680	
681	    /**
682	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
683	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
684	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
685	     * being created to the same canonical key and reject a match.
686	     *
687	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
688	     * @param key the canonical key of the owner being created
689	     * @return {@code true} if some existing owner shares the key
690	     */
691	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
692	        return findExistingOwner(keyExtractor, key).isPresent();
693	    }
694	
695	    /**
696	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
697	     * shared {@code householdId}.
698	     */
699	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
700	
701	    /**
702	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
703	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
704	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
705	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
706	     *
707	     * @param value the raw field value, or {@code null}
708	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
709	     */
710	    private String canonicalizeHousehold(String value) {
711	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
712	    }
713	
714	    /**
715	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
716	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
717	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
718	     * for the last-name normalization), so every owner with the same last name and postcode -
719	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
720	     * a postcode have no household basis and are given no household id ({@code null}).
721	     *
722	     * @param owner the owner being created
723	     * @return the shared household identifier, or {@code null} when the owner has no postcode
724	     */
725	    private String householdId(Owner owner) {
726	        String postcode = owner.getPostcode();
727	        if (postcode == null || postcode.isBlank()) {
728	            return null;
729	        }
730	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
731	        return hashPrefix(key, HOUSEHOLD_ID_LENGTH);
732	    }
733	
734	    /**
735	     * Number of leading hex characters of the household hash retained as the shared
736	     * {@code householdId}.
737	     */
738	    private static final int HOUSEHOLD_ID_LENGTH = 12;
739	
740	    /**
741	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
742	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
743	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
744	     * so every such identifier is produced by the same algorithm and differs only in the value it
745	     * hashes and the number of hex characters it keeps.
746	     *
747	     * @param input the value to hash
748	     * @param length the number of leading hex characters to keep
749	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
750	     */
751	    private String hashPrefix(String input, int length) {
752	        try {
753	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
754	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
755	            StringBuilder sb = new StringBuilder(digest.length * 2);
756	            for (byte b : digest) {
757	                sb.append(String.format("%02X", b));
758	            }
759	            return sb.substring(0, length);
760	        } catch (java.security.NoSuchAlgorithmException e) {
761	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
762	        }
763	    }
764	}
